## 1) `sql/criar_base.sql`

```sql
-- ============================================================================
-- APPLICATIVO CHAT SIMPLIFICADO — CRIAÇÃO DO BANCO DE DADOS
-- Exija: MySQL 5.7+ / MariaDB 10.3+ (InnoDB, UTF-8mb4)
-- Após rodar este script, confira as credenciais (DB_HOST, DB_USER, DB_PASS,
-- DB_NAME) no arquivo src/conexao.php ou via variáveis de ambiente.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS chat_app
  CHARACTER SET = utf8mb4
  COLLATE = utf8mb4_unicode_ci
  ENGINE = InnoDB;

USE chat_app;
SET FOREIGN_KEY_CHECK = 0;

CREATE TABLE usuarios (
  id                INT AUTO_INCREMENT PRIMARY KEY,
  nome              VARCHAR(80) NOT NULL COMMENT 'Nome de exibição. Sem aspas.',
  email             VARCHAR(120) NOT NULL UNIQUE,
  senha             VARCHAR(255) NOT NULL COMMENT 'Hash bcrypt gerado com password_hash().',
  senha_privacidade VARCHAR(255) DEFAULT NULL COMMENT 'Hash OPCIONAL: protege o perfil de terceiros.',
  avatar            VARCHAR(200) DEFAULT '' COMMENT 'Caminho da foto de perfil.',
  bio               TEXT DEFAULT '',
  status            ENUM('offline','online') DEFAULT 'offline',
  criado_em         TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  ultimo_acesso     TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE conversas (
  id                INT AUTO_INCREMENT PRIMARY KEY,
  usuario_a_id      INT NOT NULL,
  usuario_b_id      INT NOT NULL,
  criador_id        INT NOT NULL,
  titulo            VARCHAR(120) DEFAULT '',
  lido_at           TIMESTAMP NULL COMMENT 'Marca quando o dono abriu a conversa.',
  ultimo_mensagem_em TIMESTAMP NULL,
  criado_em         TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_conv_ordem (criador_id, ultimo_mensagem_em DESC),
  INDEX idx_conv_reader (criador_id, lido_at),
  CONSTRAINT fk_conv_a  FOREIGN KEY (usuario_a_id) REFERENCES usuarios(id) ON DELETE CASCADE,
  CONSTRAINT fk_conv_b  FOREIGN KEY (usuario_b_id) REFERENCES usuarios(id) ON DELETE CASCADE,
  CONSTRAINT fk_conv_c  FOREIGN KEY (criador_id) REFERENCES usuarios(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE mensagens (
  id                INT AUTO_INCREMENT PRIMARY KEY,
  conversa_id       INT NOT NULL,
  autor_id          INT NOT NULL,
  texto             VARCHAR(500) NOT NULL,
  enviado_em        TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_conv_env (conversa_id, enviado_em DESC),
  CONSTRAINT fk_msg_conv FOREIGN KEY (conversa_id) REFERENCES conversas(id) ON DELETE CASCADE,
  CONSTRAINT fk_msg_autor FOREIGN KEY (autor_id) REFERENCES usuarios(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sessions (
  id            BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  usuario_id    INT NOT NULL,
  dados         JSON NOT NULL COMMENT 'Dados de sessão serializados (id + nome).',
  criado_at     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  INDEX idx_sess_criado (criado_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Sementes para TESTES (troque as senhas se quiser outra demo).
--   admin@chat.app  → sem senha_privacidade → perfil PÚBLICO
--   ana@chat.app    → senha = "senha123" → perfil PROTEGIDO
INSERT INTO usuarios (nome, email, senha, status) VALUES
 ('Demo Admin', 'admin@chat.app', PASSWORD_HASH('admin123', PASSWORD_DEFAULT), 'offline'),
 ('Ana Demo',     'ana@chat.app',  PASSWORD_HASH('senha_ana',   PASSWORD_DEFAULT), 'offline');

SET FOREIGN_KEY_CHECK = 1;
```

