## 2) `src/conexao.php`

```php
<?php
/**
 * Conexão PDO com o banco de dados.
 * Credenciais: variáveis de ambiente (DB_HOST/DB_USER/DB_PASS/DB_NAME)
 * ou constantes no topo do arquivo (fallback).
 */

/** @var PDO|null */
$pdo = null;

function db(): PDO
{
    global $pdo;
    if ($pdo !== null) { return $pdo; }

    $host = getenv('DB_HOST') ?: (defined('DB_HOST') ? DB_HOST : 'localhost');
    $user = getenv('DB_USER') ?: (defined('DB_USER') ? DB_USER : 'root');
    $pass = getenv('DB_PASS') ?: (defined('DB_PASS') ? DB_PASS : '');
    $name = getenv('DB_NAME') ?: (defined('DB_NAME') ? DB_NAME : 'chat_app');

    try {
        $pdo = new PDO("mysql:host={$host};dbname={$name}", $user, $pass, [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_TIMEOUT            => 5,
        ]);
        $pdo->setAttribute(PDO::ATTR_STRINGIFY_PARAMS, false);
        $pdo->exec("SET NAMES 'UTF8MB4'");
    } catch (PDOException $e) {
        fatalErro("Banco de dados indisponível: " . $e->getMessage());
    }
    return $pdo;
}

function fatalErro(string $msg): void
{
    ob_end_clean();
    try {
        echo '<!DOCTYPE html>
