function httpStatus(int $codigo, string $mensagem = ''): void
{
    static $nomes = [400 => 'Bad Request', 403 => 'Acesso proibido', 404 => 'Não encontrado',
        401 => 'Não autenticado', 409 => 'Conflito', 500 => 'Erro interno', 503 => 'Indisponível'];
