(function(){
  const campos = ['nome','email','senha','senha2'];
  const btn    = document.querySelector('form button[type=submit]');
  function validar(){
    let ok = true;
    campos.forEach(id => {
      if (!document.getElementById(id).value.trim()) ok = false;
    });
    const e = document.getElementById('email').value.trim();
    if (!/^[^\\s@]+@[^\\s@]+\\.[a-zA-Z]{2,}$/.test(e)) ok = false;
    const s = document.getElementById('senha').value; const cs = document.getElementById('senha2').value;
    if (s && cs && s !== cs) ok = false;
    if (!ok) { btn.disabled = true; btn.textContent = 'Corrija e envie'; return; }
    btn.disabled = false; btn.textContent = 'Criar conta';
    const fd = new FormData(document.querySelector('form'));
    fetch('cadastrar.php', { method:'POST', credentials:'same-origin', body: fd })
      .then(r => {
        const html = r.text;
        const erroEl = document.querySelector('.alert.alert-danger');
        const okEl = document.querySelector('.alert.alert-success');
        if (okEl){ okEl.remove(); }
        if (erroEl){ erroEl.remove(); }
        const frase = html.split(/[.!?]\\s+/).filter(Boolean).slice(0,1)[0] || 'Erro no envio. Tente novamente.';
        const el = document.createElement('div');
        el.className = 'alert alert-danger d-inline-flex align-items-center gap-1';
        el.innerHTML = '<svg class="bi bi-exclamation-triangle-fill" width="16" height="16" viewBox="0 0 18 18"><path d="M9 3 14 8l-5 5-5-5z" fill="#fff"/></svg><strong>' + frase.replace(/\\/g,'') + '</strong>';
        document.querySelector('.card-body').insertBefore(el, document.querySelector('.card-body').firstElementChild || null);
      }).catch(() => {
        const el = document.createElement('div');
        el.className = 'alert alert-danger d-inline-flex align-items-center gap-1';
        el.innerHTML = '<svg class="bi bi-exclamation-triangle-fill" width="16" height="16" viewBox="0 0 18 18"><path d="M9 3 14 8l-5 5-5-5z" fill="#fff"/></svg><strong>Falha de conexão. Recarregue a página.</strong>';
        document.querySelector('.card-body').appendChild(el);
      });
  }
  document.addEventListener('input', validar);
  btn.addEventListener('click', validar);
})();
</script>
</body></html>
