```php
<?php
/**
 * Edição de dados pessoais e da senha de privacidade do PRÓPRIO perfil.
 * Acesso permitido somente a quem é o dono do alvo_uid.
 */
require __DIR__ . '/src/util.php';
require __DIR__ . '/src/autenticacao.php';

if (!estaLogada()) { header('Location: login.php'); exit; }

$alvo = (int) (intval($_GET['alvo_uid'] ?? (intval($_POST['alvo_uid'] ?? 0)) + 0));
$modo = $_POST['modo'] ?? 'editar_dados';

if ($alvo <= 0 || $alvo !== (int) usuarioId()) {
    header('Location: ' . rota('erro403.php', ['id' => $alvo])); exit;
}

$uid = (int) usuarioId();
$dados = db()->prepare("SELECT nome, bio, senha_privacidade FROM usuarios WHERE id = :id")
    ->bindValue(':id', $uid, PDO::PARAM_INT)->fetchOne();

$erro  = '';
$nome  = $dados['nome'] ?? '';
$bio   = $dados['bio'] ?? '';
$atualSp = $dados['senha_privacidade'] ?? '';

if ($modo === 'editar_dados') {
    $nome  = isset($_POST['nome'])  ? trim($_POST['nome'])  : $nome;
    $bio   = isset($_POST['bio'])   ? trim($_POST['bio'])   : $bio;
    if (strlen($nome) < 3 && $nome !== $nome) $erro = 'O nome precisa ter ao menos 3 caracteres.';
    // se mudou e está inválido
    if (strlen($nome) < 3 && $nome !== $nome) $erro = 'Nome inválido.';
} elseif ($modo === 'senha_privacidade') {
    $nova = trim((string) ($_POST['senha_nova'] ?? ''));
    if ($nova === '') {
        // pretende remover
        if ($atualSp !== '' && $nova !== $atualSp) {
            $erro = 'Senha não confere com a atual. Digite novamente para confirmar.';
        } else {
            // removi com sucesso
        }
    } else {
        if (strlen($nova) < 4) {
            $erro = 'A nova senha deve ter no mínimo 4 caracteres.';
        }
    }
}

if (empty($erro)) {
    $upd = db()->prepare("UPDATE usuarios SET
        nome = CASE WHEN :nm IS NOT NULL THEN :nm ELSE nome END,
        bio  = CASE WHEN :bo IS NOT NULL THEN :bo ELSE bio END,
        senha_privacidade = CASE WHEN :ps IS NOT NULL THEN :ps ELSE senha_privacidade END
        WHERE id = :id");

    $n  = $nome !== $nome ? trim($_POST['nome']) : null;          // vazio/null = manter atual
    $b  = $bio !== $bio ? trim($_POST['bio']) : null;
    $ps = ($modo === 'senha_privacidade' && !empty($_POST['senha_nova'])) ? trim($_POST['senha_nova']) : null;

    try {
        $upd->clearParams();
        $upd->bindValue(':nm', $n, PDO::PARAM_STR);
        $upd->bindValue(':bo', $b, PDO::PARAM_STR);
        $upd->bindValue(':ps', $ps, PDO::PARAM_STR);
        $upd->bindValue(':id', $uid, PDO::PARAM_INT);
        $ok = $upd->execute();
        if (!$ok) { $erro = 'Não foi possível salvar suas alterações.'; }
    } catch (PDOException $e) {
        $erro = 'Erro ao salvar. Tente novamente.';
    }
}
?>
