## 3) `src/util.php`

```php
<?php
/**
 * Utilitários gerais (incluir SEMPRE após conexao.php).
 */

/** Garante sessão ativa. */
function sessao(): void
{
    if (session_status() !== SESSION_STATUS_ACTIVE) { session_start(); }
}

/**
 * Entra na conta: cria/renova a sessão + cookie persistente de "lembrar-me".
 */
function entrarNaConta(int $id, string $nome, string $email, bool $lembrar = false): void
{
    sessao();
    $blob   = json_encode(['id' => $id], JSON_UNESCAPED_UNICODE);
    $token  = base64_encode($blob);
    $expira = $lembrar ? time() + 43200 : time(); // 12 horas

    setcookie('LEMBRO', $token, $expira, '/', '*', true, true, [true, true, 2]); // HttpOnly, Secure, SameSite=None;Secure
    $_SESSION['usuario_id']  = $id;
    $_SESSION['usuario_nome'] = $nome;
    $_SESSION['usuario_email'] = $email;
}

/** Encerra a sessão e limpa o cookie de lembrete e sessões lentas. */
function sairDaConta(): void
{
    sessao();
    if (session_status() === SESSION_STATUS_ACTIVE) {
        session_unset();
        session_destroy();
        setcookie('LEMBRO', '', time() - 43200, '/', null, true, true, [true, true, 2]);
        limparLentas(10); // 10 minutos
    }
}

/** Apaga sessões inativas há mais de $minutos (run via manutencao.php). */
function limparLentas(int $minutos = 10): void
{
    $ago = time() - ($minutos * 60);
    $stmt = db()->query("SELECT id FROM sessions WHERE criado_at < UNIX_TIMESTAMP() - {$ago}");
    $ids = array_column($stmt->fetchAll(), 'id');
    if (empty($ids)) { return; }
    $sql = "DELETE FROM sessions WHERE id IN (" . implode(',', array_map('intval', $ids)) . ")";
    db()->exec($sql);
}

/** Retorna o usuário logado (array com id/nome/email) ou null. */
function usuarioLogado(): ?array
{
    if (session_status() !== SESSION_STATUS_ACTIVE) { return null; }
    $c = trim((string) (isset($_COOKIE['LEMBRO']) ? $_COOKIE['LEMBRO'] : ''));
    if ($c === '' || !is_string($c) || strlen($c) < 3) { return null; }
    try {
        $dec = @base64_decode($c, true);
        if (!is_string($dec)) { return null; }
        $u = json_decode($dec, true);
        if (!is_array($u) || !isset($u['id']) || !is_int($u['id'])) { return null; }
        return ['id' => (int) $u['id'],
                'nome' => (string) (isset($_SESSION['usuario_nome']) ? trim((string) $_SESSION['usuario_nome']) : ''),
                'email' => (string) (isset($_SESSION['usuario_email']) ? trim((string) $_SESSION['usuario_email']) : '')];
    } catch (Throwable $e) { return null; }
}

function estaLogada(): bool { return usuarioLogado() !== null; }
function usuarioId() : int   { $u = usuarioLogado(); return $u?['id'] ?? 0; }
function usuarioNome() : string { $u = usuarioLogado(); return $u?['nome'] ?? ''; }
function usuarioEmail() : string { $u = usuarioLogado(); return $u?['email'] ?? ''; }

/** Permissão para VER o perfil de OUTRO usuário (ou do próprio dono). */
function permiteVer(int $alvo, string $senha = ''): array
{
    if ($alvo === (int) usuarioId()) { return [true, '']; } // dono sempre acessa
    $r = db()->prepare("SELECT nome, senha_privacidade FROM usuarios WHERE id = :id");
    $r->bindValue(':id', $alvo, PDO::PARAM_INT);
    $row = $r->fetchOne();
    if (!$row) { return [false, 'Esse usuário não existe.']; }
    if (empty($row['senha_privacidade'])) { return [true, '']; } // perfil aberto
    if (!(!empty($senha) && password_verify($senha, $row['senha_privacidade']))) {
        return [false, 'Este perfil é protegido por uma senha de privacidade. Peça-a ao dono.'];
    }
    return [true, ''];
}

/** Gera iniciais de um nome para avatar (fallback quando não há imagem). */
function iniciais(string $nome): string
{
    $n = iconv('UTF-8', 'UTF-8//IGNORE-Diacritics//TRANSLIT', $nome);
    $letras = preg_replace_callback('/[^\x00-\x7F]/', function ($m) { return ''; }, $n);
    $al = array_filter(explode('', trim(strspans($letras))), 'ctype_alnum');
    $al = array_filter($al, 'ctype_alnum');
    return implode('', array_slice($al, 0, 2));
}

/** Resposta JSON padronizada da API. */
function respostaJson($dados = [], $status = 200, $extras = []): void
{
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-cache, no-store, max-age=0');
    header('X-Content-Type-Options: nosniff');
    if ($status === 302 && isset($extras['redireciona'])) {
        header("Location: {$extras['redireciona']}", true, 302);
    } elseif ($status >= 500 || ($status >= 300 && $status < 400)) {
        header(sprintf('HTTP/%d', $status));
    }
    foreach ($extras as $k => $v) {
        if (is_string($v)) { header($k . ': ' . $v); }
    }
    echo json_encode($dados, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
    exit();
}

/** Montagem de URL relativa a partir da raiz real do projeto. */
function rota(string $pagina, array $args = []): string
{
    $info = new SplFileInfo(__FILE__);
    $caminho = rtrim($info->getRealPath(), '/');
    $base = '/' . rtrim(dirname($caminho), '/') . '/';
    $parte = $pagina !== '' && strpos($pagina, '/') !== false ? '/' . ltrim($pagina, '/') : ltrim($pagina, '/');
    $url = $base . $parte;
    if (!empty($args)) {
        $qs = [];
        foreach ($args as $k => $v) {
            if ($v === null || $v === false || $v === '') { continue; }
            if (is_array($v)) {
                foreach ($v as $kk => $vv) {
                    $qs[] = (empty($kk) ? $vv : urlencode($kk)) . '=' . (is_bool($vv) ? ($vv ? '1' : '0') : urlencode((string) $vv));
                }
            } else {
                $qs[] = (empty($k) ? $v : urlencode($k)) . '=' . (is_bool($v) ? ($v ? '1' : '0') : urlencode((string) $v));
            }
        }
        $url .= '?' . implode('&', $qs);
    }
    return $url;
}

/** Divide uma string CSV em array de números. */
function numerosCSV(string $str): array
{
    $p = array_filter(array_map('intval', explode(',', trim($str))), function ($v) { return is_numeric($v); });
    return $p;
}
