<?php
/**
 * Rotinas de login e logout. Inclua junto com conexao.php e util.php.
 */
require __DIR__ . '/../conexao.php';
require __DIR__ . '/../util.php';

/** Valida e processa o login. Retorna ['sucesso'=>bool, 'erro'=>str, 'redireciona'=>str]. */
function processarEntrada(): array
{
    $email  = trim((string) ($_POST['email'] ?? ''));
    $senha  = trim((string) ($_POST['senha'] ?? '');
    $lembrar = (bool) (isset($_POST['lembrar_me']) && $_POST['lembrar_me'] === 'on');

    if ($email === '' || $senha === '') {
        return ['sucesso' => false, 'erro' => 'Informe e-mail e senha.', 'redireciona' => 'login.php'];
    }
    if (!preg_match('/^[^\\s@]+@[^\\s@]+\\.[a-zA-Z]{2,}/i', $email)) {
        return ['sucesso' => false, 'erro' => 'E-mail inválido.', 'redireciona' => 'login.php'];
    }

    $pdo = db();
    $st  = $pdo->prepare("SELECT id, nome, senha FROM usuarios WHERE email = :e LIMIT 1");
    $st->bindValue(':e', $email, PDO::PARAM_STR);
    $row = $st->fetchOne();

    if (!$row || !password_verify($senha, $row['senha'])) {
        return ['sucesso' => false, 'erro' => 'E-mail não encontrado ou senha incorreta.', 'redireciona' => 'login.php'];
    }

    entrarNaConta((int) $row['id'], $row['nome'], $row['email'], $lembrar);
    return ['sucesso' => true, 'redireciona' => 'home.php'];
}

/** Encerra o login e redireciona. */
function processarSaida(): void
{
    sairDaConta();
    header('Location: home.php');
    exit;
}
