<?php
/**
 * Endpoint único de conversas:
 *   ?a=listar        → lista das conversas do usuário
 *   ?a=ultimas&id=X  → histórico (últimas 60 mensagens)
 *   ?a=minhas        → lista para o perfil pessoal
 *   ?a=novas&ids=1,2,3&desde=...&meu_id=... → novas mensagens ( polling )
 */
require __DIR__ . '/../conexao.php';
require __DIR__ . '/../util.php';

$uid = (int) (usuarioId() ?? 0);
$action = $_GET['a'] ?? '';

switch ($action) {

 case 'listar':
 {
     $limite = max(1, (int) (isset($_GET['limite']) ? $_GET['limite'] : 40));
     $ordem  = strtolower((string) (isset($_GET['ordenar']) ? $_GET['ordenar'] : 'desc'));
     $asc    = ($ordem === 'asc');

     $sql = <<<'SQL'
SELECT
    c.id                           AS conversa_id,
    c.titulo,
    CASE WHEN c.criador_id = :meu THEN TRUE ELSE FALSE END AS sou_criador,
    m.autor_id,
    u.nome                         AS ultimo_enviado,
    m.texto                        AS ultima_mensagem,
    DATE_FORMAT(m.enviado_em, '%d/%m %H:%M') AS hora,
    m.enviado_em                   AS ultimo_ts
FROM conversas c
LEFT JOIN mensagens m ON m.conversa_id = c.id
    AND m.enviado_em = (SELECT MAX(x.enviado_em) FROM mensagens x WHERE x.conversa_id = c.id)
LEFT JOIN usuarios u ON u.id = m.autor_id
WHERE (c.criador_id = :meu OR c.usuario_a_id = :meu OR c.usuario_b_id = :meu)
ORDER BY c.ultimo_ts {$asc ? 'ASC' : 'DESC'}
LIMIT :lim
SQL;

     $st = db()->prepare($sql);
     $st->bindValue(':meu', $uid, PDO::PARAM_INT);
     $st->bindValue(':lim', $limite, PDO::PARAM_INT);
     $rows = $st->fetchAll();

     $dados = [];
     foreach ($rows as $r) {
         $dados[] = [
             'conversa_id' => (int) $r['conversa_id'],
             'titulo'      => trim((string) $r['titulo']),
             'sou_criador' => (bool) $r['sou_criador'],
             'sou_autor'   => (int) $r['autor_id'] === $uid,
             'ultimo_enviado' => trim((string) $r['ultimo_enviado']),
             'ultima_mensagem' => trim((string) $r['ultima_mensagem'] ?? ''),
             'hora'        => (string) $r['hora'],
             'ts'          => (int) $r['ultimo_ts'],
         ];
     }
     respostaJson(['dados' => $dados, 'total' => count($dados)]);
     break;
 }

 case 'ultimas':
 {
     $id    = (int) (intval($_GET['id'] ?? 0) + 0);
     $desde = intval($_GET['desde'] ?? 0);
     if ($id <= 0) { respostaJson(['erro' => 'Conversa inválida.'], 404); exit; }
     $sql = "SELECT id, autor_id, texto, enviado_em FROM mensagens
             WHERE conversa_id = :id AND enviado_em > :desde
             ORDER BY enviado_em ASC LIMIT 60";
     $st = db()->prepare($sql);
     $st->bindValue(':id', $id, PDO::PARAM_INT);
     $st->bindValue(':desde', $desde, PDO::PARAM_INT);
     respostaJson(['mensagens' => $st->fetchAll()]);
     break;
 }

 case 'minhas':
 {
     $limite = max(1, (int) (isset($_GET['limite']) ? $_GET['limite'] : 30));
     $ordem  = strtolower((string) (isset($_GET['ordenar']) ? $_GET['ordenar'] : 'desc'));
     $asc    = ($ordem === 'asc');

     $sql = <<<'SQL'
SELECT
    c.id                           AS conversa_id,
    c.titulo,
    CASE WHEN c.criador_id = :meu THEN TRUE ELSE FALSE END AS sou_criador,
    m.autor_id,
    u.nome                         AS ultimo_enviado,
    DATE_FORMAT(m.enviado_em, '%d/%m %H:%M') AS hora
FROM conversas c
LEFT JOIN mensagens m ON m.conversa_id = c.id
    AND m.enviado_em = (SELECT MAX(x.enviado_em) FROM mensagens x WHERE x.conversa_id = c.id)
LEFT JOIN usuarios u ON u.id = m.autor_id
WHERE (c.criador_id = :meu OR c.usuario_a_id = :meu OR c.usuario_b_id = :meu)
ORDER BY c.ultimo_ts {$asc ? 'ASC' : 'DESC'}
LIMIT :lim
SQL;

     $st = db()->prepare($sql);
     $st->bindValue(':meu', $uid, PDO::PARAM_INT);
     $st->bindValue(':lim', $limite, PDO::PARAM_INT);
     $rows = $st->fetchAll();

     $dados = [];
     foreach ($rows as $r) {
         $dados[] = [
             'conversa_id' => (int) $r['conversa_id'],
             'sou_autor'   => (int) $r['autor_id'] === $uid,
             'ultimo_enviado' => trim((string) $r['ultimo_enviado']),
             'hora'        => (string) $r['hora'],
         ];
     }
     respostaJson(['dados' => $dados]);
     break;
 }

 case 'novas':
 {
     $ids      = numerosCSV($_GET['ids'] ?? '');
     if (empty($ids)) { respostaJson([]); exit; }
     $desde = intval($_GET['desde'] ?? 0);

     $sq = []; $i = 1;
     foreach ($ids as $vid) {
         $sq[] = '?';
         db()->prepare("SELECT id FROM mensagens WHERE conversa_id = ?")->bindValue($vid, PDO::PARAM_INT)->rowCount(); // apenas ocupação
     }
     // Construção correta do IN (placeholders na ordem dos binds)
     $sql = "SELECT c.id AS conversa_id, m.autor_id, m.texto, m.enviado_em
             FROM mensagens m
             INNER JOIN conversas c ON c.id = m.conversa_id
             WHERE m.conversa_id IN (
                   " . implode(",", $sq) . "
                 ) AND m.enviado_em > :desde
             ORDER BY m.enviado_em DESC LIMIT 80";

     $st = db()->prepare($sql);
     $indices = []; $j = 1;
     foreach ($ids as $vid) {
         $indices[$vid] = $j++;
         $st->bindValue(":id_" . $indices[$vid], (int) $vid, PDO::PARAM_INT);
     }
     $st->bindValue(':desde', $desde, PDO::PARAM_INT);
     $res = $st->fetchAll();

     // Remove mensagens do próprio usuário (pedido com meu_id)
     if (isset($_GET['meu_id']) && (int) $_GET['meu_id'] === $uid) {
         $res = array_filter($res, function ($m) use ($uid) { return (int) $m['autor_id'] !== $uid; });
     }

     respostaJson(['novas' => $res]);
     break;
 }

 default:
     respostaJson([]);
 }
