```php
<?php
/**
 * Recebe uma nova mensagem e a grava na conversa. Também marca leituras.
 */
require __DIR__ . '/../conexao.php';
require __DIR__ . '/../util.php';

if (!usuarioLogado()) {
    respostaJson(['ok' => false, 'msg' => 'Faça login para enviar mensagens.'], 302, ['redireciona' => 'login.php']);
    exit;
}

$conversaId = (int) (intval($_GET['conversa_id'] ?? 0) + 0);
if ($conversaId <= 0) { respostaJson(['ok' => false, 'msg' => 'Conversa inválida.'], 400); exit; }

$texto = trim((string) ($_POST['texto'] ?? ''));
if ($texto === '' || strlen($texto) < 1) { respostaJson(['ok' => false, 'msg' => 'Digite ao menos 1 caractere.'], 400); exit; }

$meuId = usuarioId();
$agora    = time();
$janela   = $agora - 2; // evita reenvio dentro dos últimos 2 segundos

$dupe = db()->query(
    "SELECT id FROM mensagens WHERE conversa_id = :cid AND autor_id = :meu AND texto = :txt AND enviado_em >= :ja LIMIT 1"
)->bindValue(':cid', $conversaId, PDO::PARAM_INT)
 ->bindValue(':meu', $meuId, PDO::PARAM_INT)
 ->bindValue(':txt', $texto, PDO::PARAM_STR)
 ->bindValue(':ja', date('Y-m-d H:i:s', $janela), PDO::PARAM_STR)->fetchOne();

if ($dupe) {
    respostaJson(['ok' => false, 'msg' => 'Esta mensagem já foi enviada.'], 200);
    exit;
}

try {
    $ins = db()->prepare("INSERT INTO mensagens (conversa_id, autor_id, texto) VALUES (:cid, :meu, :txt)");
    $ins->bindValue(':cid', $conversaId, PDO::PARAM_INT);
    $ins->bindValue(':meu', $meuId, PDO::PARAM_INT);
    $ins->bindValue(':txt', $texto, PDO::PARAM_STR);
    $ins->execute();
} catch (PDOException $e) {
    respostaJson(['ok' => false, 'msg' => 'Falha ao enviar a mensagem. Tente novamente.'], 500);
    exit;
}

// Marca como lidas todas as conversas cujo conteúdo chegou até agora
$dbLi = db()->prepare("UPDATE conversas SET lido_at = NOW() WHERE leitor_at < NOW() AND (usuario_a_id = :meu OR usuario_b_id = :meu)");
$dbLi->bindValue(':meu', $meuId, PDO::PARAM_INT); $dbLi->execute();

// Atualiza o horário da conversa que recebeu a mensagem
$dbUp = db()->prepare("UPDATE conversas SET ultimo_mensagem_em = NOW() WHERE id = :cid");
$dbUp->bindValue(':cid', $conversaId, PDO::PARAM_INT); $dbUp->execute();

respostaJson(['ok' => true, 'msg' => 'Mensagem enviada com sucesso!'], 200);
