```js
(function () {
  'use strict';
  const API      = '/src/api/';
  const ROOT     = window.location.pathname.split('?')[0] + '/';   // '/' quando na raiz
  const STORAGE  = 'chatAppState';                                 // guarda login + contador de novas

  let estado = { cartões: [], synced: 0, polindo: false };

  // ---------- Persistência ----------
  try { const r = localStorage.getItem(STORAGE); estado = r ? JSON.parse(r) : {cartões:[],synced:0,polindo:false}; } catch (e) {}

  // ---------- Utilidades ----------
  function escHTML(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function stripTags(s) { return String(s == null ? '' : s).replace(/<[^>]+>/g, ''); }

  // ---------- Avatar (Gravatar com fallback em SVG de iniciais) ----------
  async function avataPromessa(email) {
    if (!email) return null;
    try {
      const h = await hashSha256Assincrono(email);
      return 'https://www.gravatar.com/avatar/?d=mp&s=44&gravatar_hash=' + h + '&size=44';
    } catch (e) { return null; } // sem foto → o <img> terá fallback próprio
  }
  function hashSha256Assincrono(str) {
    const enc = new TextEncoder().encode(str);
    const buf = await crypto.subtle.digest('SHA-256', enc);
    const ua = new Uint8Array(buf);
    const a = new ArrayBuffer(16);
    for (let i = 0; i < 16; i++) a.writeInt8(ua[i], i);
    return [...new Uint8Array(a)].map(b => b.toString(16).padStart(2,'0')).join('');
  }
  function iniciaisAvatar(nome) {
    const letras = String(nome || '').toLowerCase().match(/[a-z]/gi) || [];
    const codigos = (letras.slice(0,2).map(c => c.toUpperCase()).join('') || '??');
    const t = Math.max(28, Math.min(36, Math.round(letras.length < 2 ? 28 : 30)));
    return 'data:image/svg+xml;base64,' + btoa('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + (t*2) + ' ' + (t*2) + '" width="' + (t*2) + '" height="' + (t*2) + '" class="rounded-circle" style="object-fit:cover;display:block;background:#eef2f6;color:#333f58"><text x="50%" y="52%" text-anchor="middle" font-family="system-ui,sans-serif" font-size="' + Math.max(22, t*.65) + '" font-weight="700">' + codigos + '</text></svg>').replace(/=+$/, '');
  }

  // ---------- Modelos de card ----------
  function tarjeta(c) {
    const ts  = c.ts;
    const contagem = (estado.contagens && estado.contagens.get(c.id)) ? parseInt(estado.contagens.get(c.id), 10) : 0;
    const nova = ts && Math.floor(ts * 1000) > Math.floor(estado.synced * 1000);
    const voceTag = c.souAutor ? '<span class="badge badge-neutra ml-1">você</span>' : '';
    const msgLimpo = stripTags(c.ultima_mensagem || '').slice(0, 54);
    return `
      <div class="chat-card d-flex align-items-center gap-1 py-2 px-2 cursor-pointer border-0 shadow-sm"
           data-id="${c.id}"
           onclick="abrirConversa(${c.id})"
           ${nova ? 'class="nova-temp"' : ''}>
        <div class="avata flex-shrink-0">
          <img class="rounded-circle avatar-sm" src="${avataPromessa(c.ultimo_enviado || c.titulo).then(u => { img.src=u; })}"
               alt="${escHTML(c.ultimo_enviado || 'Usuário')}"
               onerror="this.src='';this.parentElement.innerHTML='<span class=\"text-muted fs-6\">${iniciaisAvatar(c.ultimo_enviado || c.titulo)}</span>'">
        </div>
        <div class="info flex-grow-1 min-w-0">
          <div class="fw-semibold small" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#333f58">${escHTML(c.ultimo_enviado)}</div>
          ${voceTag}
          <small class="msg-preview" style="font-size:.78em;color:#8a9aa6">${msgLimpo}</small>
          <small class="time" style="font-size:.7em;color:#9cb1bd">${momentoDatas(ts)}</small>
        </div>
        ${nova && contagem > 0 ? '<span class="badge badge-nova ml-auto">' + (contagem > 99 ? '99+' : contagem) + ' novas</span>' : ''}
      </div>`;
  }

  function momentoDatas(ts) {
    if (!ts) return '';
    const d = new Date(ts * 1000);
    const h = d.getHours();
    const ampm = h < 12 ? (h = h || 12 ? '12' : '0' + String(h).slice(1)) : (h = h - 12 < 10 ? h : h - 12);
    return d.toLocaleDateString('pt-BR', {day:'2-digit',month:'short'}) + ' ' + d.toLocaleTimeString('pt-BR', {hour:'2-digit',minute:'2-digit'});
  }

  // ---------- Renderização ----------
  function renderLista(){
    const dom = document.getElementById('lista-conversas');
    if (!dom) return;
    const itens = [...estado.cartoes];
    dom.innerHTML = itens.map(tarjeta).join('');
    reaplicarContadores();
  }

  function reaplicarContadores(){
    document.querySelectorAll('#lista-conversas .chat-card').forEach(el => {
      const id = parseInt(el.dataset.id, 10);
      const contagem = (estado.contagens && estado.contagens.has(id)) ? parseInt(estado.contagens.get(id), 10) : 0;
      const antes = parseInt(el.dataset.contagem || '0', 10);
      el.dataset.contagem = Math.min(99, antes); // será incrementado pelas chegadas
      el.classList.toggle('nova-temp', contagem > 0 && antes === 0);
    });
  }

  // ---------- Novas mensagens ----------
  function processarChegadas(mensagens){
    if (!mensagens.length) return;
    const grupo = {};
    mensagens.forEach(m => { grupo[m.conversa_id] = (grupo[m.conversa_id]||0) + 1; });

    document.querySelectorAll('#lista-conversas .chat-card').forEach(card => {
      const id = parseInt(card.dataset.id, 10);
      const delta = grupo[id] || 0;
      const antes = parseInt(card.dataset.contagem || '0', 10);
      const depois = Math.min(99, antes + delta);
      card.dataset.contagem = String(depois);
      if (depois > 0) card.classList.add('nova-temp');
      else card.classList.remove('nova-temp');
    });

    // badge no topo da lista
    const tot = [...document.querySelectorAll('#lista-conversas .chat-card')]
      .reduce((s, c) => s + ((parseInt(c.dataset.contagem||0)>0)?1:0), 0);
    const aviso = document.getElementById('aviso-novas');
    if (aviso) aviso.textContent = tot > 0 ? tot + ' nova' + (tot > 1 ? 's' : '') : '';
    aviso.style.display = tot > 0 ? '' : 'none';

    // avança o ponto de sincronização
    const ultTs = mensagens.reduce((mx, m) => {
      if (!m.data) return mx;
      return Math.max(mx, Math.floor(new Date(m.data).getTime()/1000));
    }, -1);
    estado.synced = Math.max(estado.synced, ultTs);
  }

  // ---------- Carga inicial ----------
  async function carregarConversas(ordem){
    if (estado.polindo) return;
    estado.polindo = true;
    const qs = new URLSearchParams(window.location.search);
    let url = ROOT + 'src/api/conversas.php?a=listar&limite=60&ordenar=' + ordem;
    if (qs.has('id')) url += '&' + qs.get('id');

    try {
      const r = await fetch(url, { credentials: 'same-origin' });
      if (r.status === 302) throw new Error('redirecionado');
      const j = await r.json();
      estado.cartoes = (j.dados || []).map(c => ({
        id: c.conversa_id, ultimo_enviado: c.ultimo_enviado, titulo: c.titulo,
        souAutor: c.sou_autor, ultima_mensagem: c.ultima_mensagem, ts: c.ts
      }));
      try { localStorage.setItem(STORAGE, JSON.stringify(estado)); } catch(e){}
      renderLista();
      processarChegadas(j.novas || []);
      estado.synced = Math.max(estado.synced, ...(estado.cartoes.map(c => c.ts ? Math.floor(c.ts*1000) : -1)));
      setTimeout(()=> { iniciarAgenda(); }, 1200);
      estado.polindo = false;
    } catch(err){ estado.polindo = false; }
  }

  function iniciarAgenda(){
    if (!estado.cartoes.length) return;
    if (estado.polindo) return;
    estado.polindo = true;
    dispararLevas();
    const ciclo = () => {
      dispararLevas();
      setTimeout(ciclo, 10000);
    };
    ciclo();
  }

  function dispararLevas(){
    if (!estado.cartoes.length || estado.polindo) return;
    estado.polindo = true;
    const ids = [...new Set(estado.cartoes.map(c=>c.id))].join(',');
    const desde = Math.max(0, Math.floor(estado.synced*1000) - 60000);
    try {
      const r = await fetch(ROOT + 'src/api/conversas.php?a=novas&ids=' + encodeURIComponent(ids)
        + '&desde=' + Math.floor(desde/1000), { credentials: 'same-origin' });
      if (r.status === 302) throw new Error();
      const j = await r.json();
      if (j.novas && j.novas.length) processarChegadas(j.novas);
    } catch(e){ /* silêncio */ }
    estado.polindo = false;
  }

  // ---------- Busca de pessoas ----------
  let timerBusca = null;
  function buscar(){
    clearTimeout(timerBusca);
    timerBusca = setTimeout(async () => {
      const t = (document.getElementById('buscar') || document.getElementById('modal-pessoa')).value.trim();
      if (!t || t.length < 2) { esconderSugestoes(); return; }
      try {
        const r = await fetch(ROOT + 'src/api/usuarios.php?q=' + encodeURIComponent(t) + '&tipo=busca', { credentials: 'same-origin' });
        const j = await r.json();
        mostrarSugeridas(j.sugestoes || [], t, false);
      } catch(e){ esconderSugestoes(); }
    }, 350);
  }
  function esconderSugestoes(){ document.getElementById('lista-sugestoes').innerHTML = ''; }

  function mostrarSugeridas(lista, termo, interno){
    const el = document.getElementById(interno ? 'modal-sugestoes' : 'lista-sugestoes');
    if (!el) return;
    const filt = lista.filter(i => {
      const n = String(i.nome || '').toLowerCase();
      return n.indexOf(termo.toLowerCase()) === 0;
    }).slice(0, 8);
    el.innerHTML = filt.map(o => {
      const urlAvatar = avataPromessa(o.email || '').then(u => u || iniciaisAvatar(o.nome || ''));
      const alvo = interno ? ROOT + 'conversa.php?id=' + o.id : ROOT + 'src/api/usuarios.php?q=' + encodeURIComponent(o.email + '@') + '&tipo=busca';
      const blob = `<div class="d-flex align-items-center gap-1 px-2 py-1.5 rounded cursor-pointer border border:#e2e8f0 bg:#f6f8fb" onclick="${escQuote(alvo)}">
        <img class="rounded-circle avatar-sm" src="${urlAvatar.catch(()=>{})}" alt="" style="width:32px;height:32px;border-radius:50%;object-fit:cover" onerror="this.src='';this.parentElement.innerHTML='<span class=\"avatar-inicial text-muted fs-6\"></span>'">
        <div class="min-w-0 flex-1">
          <strong style="font-size:.88em">${escHTML(i.nome)}</strong>
          <small style="font-size:.72em;color:#6a788a">${escHTML(i.email)}</small>
        </div>
      </div>`;
      // evita quebra de sintaxe em onclick: o valor de alvo não contém aspas duplas
      blob = blob.replace(/\(/g, '\\(').replace(/\)/g, '\\)').replace(/'/g, "\\'");
      return blob;
    }).join('');
  }
  function escQuote(seguro) { return encodeURIComponent(seguro).replace(/'/g, '%27'); }

  // ---------- Modal nova conversa ----------
  function abrirModalNovo(){
    const m = document.getElementById('modalNovo');
    if (!m) return;
    m.classList.remove('d-none');
    m.setAttribute('aria-hidden','false');
    const inp = document.getElementById('modal-pessoa');
    if (inp) { buscar(); inp.focus(); }
  }
  function fecharModal(){ document.getElementById('modalNovo').classList.add('d-none'); document.getElementById('modalNovo').setAttribute('aria-hidden','true'); }
  function escolherDoModal(){
    const v = (document.getElementById('modal-pessoa')||'').value.trim();
    if (!v || v.length < 2) { fecharModal(); return; }
    const termo = v.startsWith('@') ? v.split('@')[1] : v;
    fetch(ROOT + 'src/api/usuarios.php?q=' + encodeURIComponent(termo) + '&tipo=busca', {credentials:'same-origin'})
      .then(r => r.ok ? r.json() : {sugestoes:[]})
      .then(j => {
        const match = j.sugestoes?.find(s => {
          const n = String(s.nome||'').toLowerCase();
          const e = String(s.email||'').toLowerCase();
          return n.indexOf(v.toLowerCase()) === 0 || e.indexOf(v.toLowerCase()) === 0;
        });
        if (!match) { fecharModal(); return; }
        window.location.href = ROOT + 'conversa.php?id=' + match.id;
        fecharModal();
      }).catch(() => fecharModal());
  }

  // ---------- Toast ----------
  function alertarToast(msg, ok){
    const el = document.createElement('div');
    el.className = 'toast-custom ' + (ok ? 'toast-sucesso' : 'toast-erro');
    const icone = ok
      ? '<svg class="toast-icon" viewBox="0 0 18 18"><circle cx="6" cy="6" r="5"/><path d="M9 3 14 8l-5 5z" fill="#fff"/></svg>'
      : '<svg class="toast-icon" viewBox="0 0 18 18"><path d="M9 3 14 8l-5 5-5-5z" fill="#fff" stroke="#fff" stroke-width="1.5"/></svg>';
    const texto = '<span style="font-weight:600;color:#292831">' + escHTML(msg) + '</span>';
    el.innerHTML = '<div class="toast-body">' + icone + texto + '</div>';
    document.body.appendChild(el);
    setTimeout(() => { el.style.animation = 'none'; el.remove(); }, 4500);
    // animação CSS de entrada: aplica fade via class
    const obs = new Observation(el);
    const evt = new CustomEvent('toast:end', { detail: el });
    window.addEventListener('toast:end', e => { obs.observe(e.detail); });
  }

  // ---------- Abertura de conversa ----------
  function abrirConversa(id){ window.location.href = ROOT + 'conversa.php?id=' + id; }

  // ---------- Inicialização ----------
  document.addEventListener('DOMContentLoaded', () => {
    carregarConversas('desc');
    // se a conversa já estiver aberta via ?id= mantém a lista; se vier da home, lista cheia já veio
    document.getElementById('buscar')?.addEventListener('input', buscar);
    document.getElementById('buscar')?.addEventListener('click', buscar);
    document.addEventListener('click', e => {
      const card = e.target.closest('.chat-card');
      if (card) abrirConversa(parseInt(card.dataset.id, 10));
    });
    document.getElementById('modalNovo')?.addEventListener('keydown', e => {
      if (e.key === 'Escape') fecharModal();
    });
  });
})();
