```js
(function () {
  'use strict';

  const meta   = document.getElementById('__meta');
  const CONVERSA_ID = isNaN(parseInt(new URL(window.location.href).searchParams.get('id'), 10))
                    ? null : parseInt(new URL(window.location.href).searchParams.get('id'), 10);
  const uid    = meta ? parseInt(meta.getAttribute('data-uid'), 10) : 0;

  if (CONVERSA_ID === null || uid === 0) { document.location.href = 'home.php'; return; }

  const API       = '/src/api/';
  const SCROLL_EL = document.getElementById('lista-mensagens');
  const CAMPO     = document.getElementById('campoMsg');
  const INDICADOR = document.getElementById('digando');
  const BADGE     = document.getElementById('contador');

  if (!SCROLL_EL || !CAMPO) { document.location.href = 'home.php'; return; }

  let ultimoTs   = Math.floor(Date.now() / 1000);
  let timer      = null;
  let bloqueado  = false;
  const nomeUsuario = meta ? meta.getAttribute('data-user-name') || 'Usuário' : 'Usuário';

  // ---------- DOM ----------
  const SCROLL = SCROLL_EL;
  function garantirScroll(){
    if (!SCROLL) return;
    SCROLL.scrollTop = SCROLL.scrollHeight - SCROLL.clientHeight - 12;
  }
  function formatoHora(data){
    return data ? new Date(data).toLocaleString('pt-BR') : new Date().toLocaleString('pt-BR');
  }

  function escDom(s) { return String(s == null ? '' : s).replace(/[<>"']/g, c => ({'<':'&lt;','>':'&gt;','"':'&quot;','&':'&amp;',"'":'&#39;'})[c]); }

  // ---------- Inserção de mensagem ----------
  function normalizarMsg(raw){
    let m;
    if (typeof raw === 'string'){
      try{ m = JSON.parse(raw); }catch(_){ m = {texto: raw}; }
    }else{ m = raw; }
    return {
      texto: String(m?.texto || '').replace(/\r?\n|\r/g,' ').trim(),
      autor_id: Number(m?.autor_id ?? 0),
      nome: (m?.nome || '').trim(),
      email: (m?.email || '').trim(),
      data: m?.data ? new Date(m?.data).toISOString() : null,
      conversa_id: m?.conversa_id ?? null,
    };
  }

  function inserir(msgs){
    for (const m of msgs) inserirUma(m);
  }

  function inserirUma(m){
    const éNosso = Number(m.autor_id ?? 0) === uid;
    const ts = m.data ? Math.floor(new Date(m.data).getTime()/1000) : Math.floor(Date.now()/1000);
    const bloco = document.createElement('div');
    bloco.className = 'mensagem ' + (éNosso ? 'me' : 'deles');
    bloco.dataset.ts = String(ts);
    bloco.dataset.conversaId = String(m.conversa_id ?? 0);

    const corpo = document.createElement('div');

    if (éNosso){
      const wrap = document.createElement('div'); wrap.className = 'media';
      const cita = document.createElement('blockquote'); cita.className = 'cita';
      cita.innerHTML = '<footer class="me-foot"><small class="text-muted">' + formatoHora(new Date()) + '</small></footer><p>' + escDom(m.texto) + '</p>';
      wrap.appendChild(cita); corpo.appendChild(wrap);
    } else {
      const coluna = document.createElement('div');
      const img = document.createElement('img');
      img.className = 'rounded-circle'; img.style.width='28px'; img.style.height='28px';
      const urlAv = obterAvatarAsync(m.email, m.nome || '');
      img.addEventListener('error', () => substituirPorInicial(img, m.nome || m.email));
      img.src = urlAv;

      const fila = document.createElement('div'); fila.className = 'flex flex-col g-0';
      fila.appendChild(img);

      const textoWrap = document.createElement('div'); textoWrap.className = 'flex flex-col g-0';
      const tempo = document.createElement('small');
      tempo.className = 'text-muted'; tempo.style.fontSize = '.66em';
      tempo.textContent = formatoHora(new Date());
      textoWrap.appendChild(tempo);

      const cita = document.createElement('blockquote');
      cita.className = 'position-relative pe-2 ps-3';
      cita.style.borderColor = 'var(--rosa-escuro)';
      cita.style.borderWidth = '3px'; cita.style.borderLeftWidth = '3px';
      cita.style.backgroundColor = '#fdf4f1'; cita.style.borderRadius = '.3rem';
      cita.innerHTML = '<p>' + escDom(m.texto) + '</p>';
      fila.appendChild(textoWrap); fila.appendChild(cita);
      corpo.appendChild(fila);
    }

    bloco.appendChild(corpo);
    SCROLL.appendChild(bloco);
    garantirScroll();
  }

  function obterAvatarAsync(email, fallback) {
    if (!email) return 'data:image/svg+xml;base64,' + btoa('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" width="64" height="64" class="rounded-circle"><circle cx="32" cy="32" r="28" fill="#eef2f6"/><text x="32" y="40" text-anchor="middle" font-family="sans-serif" font-size="26" fill="#333f58">' + (fallback.match(/[a-z]/gi)?.slice(0,2).map(c=>c.toUpperCase()).join('') || '??') + '</text></svg>').replace(/=+$/, '');
    return hashSha256Assincrono(email).then(h =>
      'https://www.gravatar.com/avatar/?d=mp&s=30&gravatar_hash=' + h + '&size=30'
    );
  }

  function substituirPorInicial(img, nome){
    img.style.display = 'none';
    const cont = img.parentElement;
    cont.insertAdjacentHTML('beforeend', '<div class="midia-avatar"></div>');
    const sv = document.createElement('div');
    sv.className = 'midia-avatar';
    sv.style.cssText = 'width:28px;height:28px;display:flex;align-items:center;justify-content:center;background:#fff;border-radius:50%;color:#333f58;font-size:.72em;font-weight:700';
    const codigos = String(nome || '').toLowerCase().match(/[a-z]/gi) || [];
    sv.innerHTML = '<svg viewBox="0 0 28 28" width="28" height="28"><circle cx="14" cy="14" r="12" fill="#eef2f6"/><text x="14" y="21" text-anchor="middle" font-size="13" fill="#333f58">' + (codigos.slice(0,2).map(c=>c.toUpperCase()).join('') || '??') + '</text></svg>';
    cont.appendChild(sv);
  }

  // ---------- Enviar ----------
  async function enviar(){
    if (!bloqueado && !CAMPO.value.trim()) return;
    bloqueado = true;
    CAMPO.value = ''; CAMPO.focus();

    try {
      const r = await fetch(API + 'enviar_mensagem.php?a=enviar&conversa_id=' + CONVERSA_ID
        + '&texto=' + encodeURIComponent(CAMPO.value.trim()), { method:'POST', credentials:'same-origin', headers:{'Accept':'application/json'} });
      const j = await r.json();
      if (j.ok){
        inserir([normalizarMsg({
          texto: CAMPO.value.trim(), autor_id: uid, nome: nomeUsuario, email: usuarioEmail(),
          data: new Date().toISOString(), conversa_id: CONVERSA_ID
        })]);
        INDICADOR.classList.add('hidden');
        garantirScroll();
        if (timer){ clearInterval(timer); timer = null; }
        setTimeout(processarChegadas, 450);
      } else {
        alertarToast(j.msg, false);
      }
    } catch(e){ alertarToast('Problema ao enviar. Tente novamente.', false); }
    bloqueado = false;
  }

  SCROLL_EL.addEventListener('wheel', e => e.preventDefault(), { passive: false }); // trava scroll ao digitar

  const btnSend = document.querySelector('.send');
  CAMPO.addEventListener('keydown', e => {
    if (e.key === 'Enter' && !e.shiftKey && !bloqueado) { e.preventDefault(); enviar(); return; }
    if (e.key === 'Tab'){
      e.preventDefault();
      if (document.activeElement === CAMPO) CAMPO.dispatchEvent(new KeyboardEvent('focus', { bubbles:true }));
      return false;
    }
  });
  if (btnSend) btnSend.addEventListener('keydown', e => { if (e.key === 'Tab' && e.shiftKey) { e.preventDefault(); CAMPO.focus(); return false; } });

  // ---------- Indicador de digitando ----------
  let campoEmFoco = false;
  CAMPO.addEventListener('focus', () => { campoEmFoco = true; (INDICADOR||document.getElementById('digando')).classList.remove('hidden'); });
  CAMPO.addEventListener('blur',  () => { campoEmFoco = false; setTimeout(()=> INDICADOR?.classList.add('hidden'), 1600); });
  CAMPO.addEventListener('input', () => { if (campoEmFoco && CAMPO.value.trim()) {
    const el = INDICADOR || document.getElementById('digando');
    if (!el.classList.contains('ativo')) el.classList.add('ativo');
  }});

  // ---------- Histórico inicial ----------
  let primeiraCarrega = true;
  document.addEventListener('DOMContentLoaded', () => {
    if (CONVERSA_ID && primeiraCarrega && !temMensagens()){
      carregarHistorico();
      setTimeout(() => { processarChegadasManual(); }, 900);
    }
    primeiraCarrega = false;
    iniciarPolling();
  });

  function temMensagens(){ return [...SCROLL_EL.querySelectorAll('.mensagem')].length > 0; }

  async function carregarHistorico(){
    const url = new URL(window.location.href);
    const desde = Math.max(0, Math.floor((Math.floor(Date.now()/1000)-280)*1000));
    const qs = URL.stringify({ a:'ultimas', id: CONVERSA_ID, desde: Math.floor(desde/1000) });
    const r = await fetch(API + 'conversas.php?' + qs, { credentials:'same-origin' });
    if (r.status === 302) throw new Error();
    const j = await r.json();
    const msgs = (j.mensagens || []).reverse();
    const container = document.getElementById('conteudo-mensamentos');
    const vazio = container?.querySelector('.vazio');
    if (!msgs.length){
      if (vazio) container.removeChild(vazio);
      return;
    }
    inserir(msgs.map(normalizarMsg));
    garantirScroll();
    // oculta o aviso vazio se existir
    const aviso = container?.querySelector('.aviso-vazio');
    if (aviso) aviso.style.display = 'none';
  }

  // ---------- Polling de novas mensagens ----------
  async function processarChegadasManual(){
    if (!CONVERSA_ID) return;
    try {
      const r = await fetch(API + 'conversas.php?a=novas&ids=' + CONVERSA_ID
        + '&desde=' + Math.max(0, Math.floor((ultimoTs-60)*1000)) + '&meu_id=' + uid, { credentials:'same-origin' });
      if (r.status === 302) throw new Error();
      const j = await r.json();
      if (j.novas && j.novas.length) {
        inserir(j.novas);
        if (j.novas.length) garantirScroll();
        sincronizarBadge();
      }
      ultimoTs = Math.max(ultimoTs, ...j.novas.map(m => m.data ? Math.floor(new Date(m.data).getTime()/1000) : -1));
    } catch(e){ /* falha silenciosa para não travar a página */ }
  }

  function iniciarPolling(){
    if (!CONVERSA_ID) return;
    processarChegadasManual();
    timer = setInterval(processarChegadasManual, 10000);
  }
  function pausarPolling(){ if (timer){ clearInterval(timer); timer = null; } }

  // ---------- Contador de novas (no cabeçalho) ----------
  function sincronizarBadge(){
    if (!BADGE || !CONVERSA_ID) return;
    const msgs = [...SCROLL_EL.querySelectorAll('.mensagem')];
    if (!msgs.length) { BADGE.textContent = '0 novas'; return; }
    const ordenado = msgs.sort((a,b) => Number(a.dataset.ts || 0) - Number(b.dataset.ts || 0));
    const ult = ordenado[0];
    if (!ult) { BADGE.textContent = '0 novas'; return; }
    const corte = Math.floor((Math.floor(Date.now()/1000) - 60) * 1000);
    const pendentes = [...msgs].filter(m => {
      const t = m.dataset.ts ? Math.floor(new Date(Number(m.dataset.ts)*1000)/1000) : 0;
      return t > Math.floor(corte/1000);
    }).length;
    BADGE.textContent = pendentes > 0 ? (pendentes > 99 ? '99+' : pendentes) + ' nova' : '0 novas';
  }

  function alertarToast(msg, ok){ alertarToast(msg, ok); }

  // ---------- Expor funções para home (abrir conversa) ----------
  window.abrirConversa = abrirConversa;
})();
