<?php
/** Criação de conta nova. Valida cliente + servidor e registra no banco. */
require __DIR__ . '/src/conexao.php';
require __DIR__ . '/src/util.php';

$sucesso = false; $erro = '';
$nome    = trim((string) ($_POST['nome'] ?? ''));
$email   = trim((string) ($_POST['email'] ?? ''));
$senha1  = trim((string) ($_POST['senha'] ?? ''));
$senha2  = trim((string) ($_POST['senha2'] ?? '');

if ($nome === '' || $email === '' || $senha1 === '' || $senha2 === '') {
    $erro = 'Preencha todos os campos obrigatórios.';
} else {
    if (strlen($nome) < 3) $erro = 'O nome precisa ter ao menos 3 caracteres.';
    if (!preg_match('/^[^\\s@]+@[^\\s@]+\\.[a-zA-Z]{2,}$/', $email)) {
        $erro = 'Informe um e-mail válido.';
    } else {
        $chk = db()->query("SELECT id FROM usuarios WHERE email = :e LIMIT 1")
            ->bindValue(':e', $email, PDO::PARAM_STR)->fetchOne();
        if ($chk) $erro = 'Esse e-mail já está cadastrado.';
    }
    if ($senha1 !== $senha2) $erro = 'As senhas não conferem.';
    if (strlen($senha1) < 6) $erro = 'A senha deve ter no mínimo 6 caracteres.';
    if (empty($erro)) {
        $hash = password_hash($senha1, PASSWORD_BCRYPT);
        $st = db()->prepare("INSERT INTO usuarios (nome, email, senha) VALUES (:n, :e, :s)");
        $st->bindValue(':n', $nome, PDO::PARAM_STR);
        $st->bindValue(':e', $email, PDO::PARAM_STR);
        $st->bindValue(':s', $hash, PDO::PARAM_STR);
        try { $st->execute(); $sucesso = true; } catch (PDOException $e) { $erro = 'Ocorreu um erro ao criar sua conta. Tente novamente.'; }
    }
}
