                           ((modo==='remover')?'<input type="hidden" name="senha_atual" value="********" required><div class="form-text text-muted">Digite a senha atual para removê-la.</div>':'') +
                           '<button class="btn btn-sm btn-primary mt-1">Salvar</button>';
