        var caixa = document.querySelector('.acoes-perfil');
        if (!caixa) caixa = document.querySelector('.card-body .d-flex'); // fallback
        if (!caixa && modoDetecionado()) return; // forma alternativa capturada abaixo
        // fallback: o form montado foi anexado em 'form-area'; recuperamos:
        const area = document.getElementById('form-area');
        if (!area) {
          // cria dinamicamente e anexa
          area = document.createElement('div');
          area.id = 'form-area';
          document.querySelector('.mt-4').parentNode ? // depende da template; simplifica abaixo
