  form.method = 'post'; form.action = 'editar-meus-dados.php';
  form.innerHTML = '<input type="hidden" name="alvo_uid" value="' + (alvo||'').replace(/'/g,'\\\'') + '">' +
                   '<input type="hidden" name="modo" value="senha_privacidade">' +
                   '<input type="hidden" name="senha_atual" value="********" required><div class="form-text text-muted">Digite a senha atual para removê-la.</div>' +
                   '<button class="btn btn-sm btn-danger" type="submit">Remover</button>';
  btn.parentNode.appendChild(form);
  btn.parentNode.removeChild(btn);
  form.submit();
}
</script>
